function g({registerIndicator:F,nulls:k}){const y=(o,i,c)=>{const l=o.length,a=new Array(l).fill(NaN),n=[];for(let e=0;e<l;e++){for(;n.length>0&&n[0]<=e-i;)n.shift();const r=o[e];if(Number.isFinite(r)){for(;n.length>0;){const s=o[n[n.length-1]];if(c?s<=r:s>=r)n.pop();else break}n.push(e)}n.length>0&&(a[e]=o[n[0]])}return a},m=(o,i,c)=>{const l=y(o,c,!0),a=y(i,c,!1),n=new Array(o.length).fill(NaN);for(let e=0;e<o.length;e++)Number.isFinite(l[e])&&Number.isFinite(a[e])&&(n[e]=(l[e]+a[e])/2);return n};F({id:"oa-ichimoku",name:"Ichimoku Cloud",category:"Dynamics",placement:"onchart",inputs:[{key:"tenkan",type:"number",label:"Tenkan Period",default:9,min:1,max:5e3,step:1},{key:"kijun",type:"number",label:"Kijun Period",default:26,min:1,max:5e3,step:1},{key:"senkouB",type:"number",label:"Senkou B Period",default:52,min:1,max:5e3,step:1},{key:"displacement",type:"number",label:"Displacement",default:26,min:1,max:500,step:1,tooltip:"Bars the cloud is pushed forward and the lagging span pulled back by."}],plots:[{key:"tenkan",type:"line",title:"Tenkan-sen",style:{color:"#2962ff",lineWidth:1}},{key:"kijun",type:"line",title:"Kijun-sen",style:{color:"#FF5252",lineWidth:1}},{key:"chikou",type:"line",title:"Chikou Span",style:{color:"#9C27B0",lineWidth:1}},{key:"senkouA",type:"line",title:"Senkou Span A",style:{color:"#4CAF50",lineWidth:1}},{key:"senkouB",type:"line",title:"Senkou Span B",style:{color:"#FF5252",lineWidth:1}}],fills:[{between:["senkouA","senkouB"],colorUp:"#4CAF50",colorDown:"#FF5252",opacity:.1}],calc(o,i){const c=Math.max(1,Math.floor(Number(i.tenkan)||9)),l=Math.max(1,Math.floor(Number(i.kijun)||26)),a=Math.max(1,Math.floor(Number(i.senkouB)||52)),n=Math.max(1,Math.floor(Number(i.displacement)||26)),e=o.length,r=o.map(t=>t.high),s=o.map(t=>t.low),h=m(r,s,c),p=m(r,s,l),B=m(r,s,a),f=new Array(e).fill(NaN),d=new Array(e).fill(NaN),N=new Array(e).fill(NaN),b=new Array(e).fill(NaN),w=new Array(e).fill(NaN);for(let t=0;t<e;t++){f[t]=h[t],d[t]=p[t];const u=t-n;u>=0&&(Number.isFinite(h[u])&&Number.isFinite(p[u])&&(N[t]=(h[u]+p[u])/2),b[t]=B[u]);const A=t+n;A<e&&(w[t]=o[A].close)}return{tenkan:k(f),kijun:k(d),chikou:k(w),senkouA:k(N),senkouB:k(b)}}})}export{g as default};
